INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400009, 'CODING', 'MEDIUM', 'CODING', 'Problem solving', 'Two Sum', 'Given n integers and a target value, find the pair of positions i < j with a[i] + a[j] = target. If several pairs exist print the pair with the smallest i, and for that i the smallest j. If no pair exists print -1. Positions start at 0.', NULL, TRUE);
