INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400014, 'CODING', 'MEDIUM', 'CODING', 'Problem solving', 'Moving Average', 'Given a series of n numbers and a window size k, print the average of every window of k consecutive numbers, rounded to two decimal places. The input guarantees that no average is exactly halfway between two rounded values.', NULL, TRUE);
INSERT INTO interview_coding_problems (question_id, constraints_text, input_format, output_format, time_limit_seconds, memory_limit_mb) VALUES (400014, '1 <= k <= n <= 1000, 0 <= values <= 1000', 'The first line contains n and k. The second line contains n integers.', 'Print n - k + 1 lines, each with an average with exactly two decimals.', 2, 256);
