INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400015, 'CODING', 'MEDIUM', 'CODING', 'Problem solving', 'Bug Triage Order', 'A QA team has n open bugs. Each bug has an id (text) and a severity from 1 (minor) to 5 (critical). Print the bug ids in the order they should be fixed: highest severity first. Bugs with the same severity are ordered by id in ordinary string order.', NULL, TRUE);
INSERT INTO interview_coding_problems (question_id, constraints_text, input_format, output_format, time_limit_seconds, memory_limit_mb) VALUES (400015, '1 <= n <= 1000', 'The first line contains n. Each of the next n lines contains a bug id and its severity.', 'Print n lines, one bug id per line.', 2, 256);
