INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400016, 'CODING', 'MEDIUM', 'CODING', 'Problem solving', 'Merge Intervals', 'Given n closed intervals [start, end], merge all intervals that overlap or touch (for example [1,3] and [3,5] become [1,5]). Print the merged intervals sorted by start.', NULL, TRUE);
