INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400020, 'CODING', 'HARD', 'CODING', 'Problem solving', 'Minimum Coins', 'You have an unlimited supply of coins of the given values. Find the minimum number of coins needed to make the exact amount. If it is impossible print -1. An amount of 0 needs 0 coins.', NULL, TRUE);
INSERT INTO interview_coding_problems (question_id, constraints_text, input_format, output_format, time_limit_seconds, memory_limit_mb) VALUES (400020, '0 <= amount <= 10000, 1 <= n <= 12, 1 <= coin <= 10000', 'The first line contains the amount and the number of coin values n. The second line contains the n coin values.', 'Print the minimum number of coins, or -1.', 2, 256);
