INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400021, 'CODING', 'HARD', 'CODING', 'Problem solving', 'Number of Islands', 'A map is a grid of 1 (land) and 0 (water). An island is a group of land cells connected horizontally or vertically. Count the islands.', NULL, TRUE);
