INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, title, question_text, explanation, active) VALUES (400026, 'CODING', 'HARD', 'CODING', 'Problem solving', 'Minimum Test Machines', 'A test lab must run n test suites. Suite i runs from start time s_i up to, but not including, end time e_i. Two suites that overlap in time cannot share a machine, but a suite may start exactly when another one ends. Print the minimum number of machines needed.', NULL, TRUE);
